&lt;html lang="en"&gt;
&lt;head&gt;
    &lt;meta charset="UTF-8"&gt;
    &lt;title&gt;Real-Time Line Graph&lt;/title&gt;
    &lt;style&gt;
        body {
            margin: 0;
            background: #0f0f23;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100vh;
            font-family: system-ui, -apple-system, sans-serif;
            color: #e0e0e0;
        }
        h2 { color: #bb86fc; margin-bottom: 12px; }
        canvas {
            background: #1a1a2e;
            border-radius: 8px;
            border: 1px solid #333;
        }
        #stats {
            margin-top: 12px;
            font-size: 14px;
            color: #888;
        }
    &lt;/style&gt;
&lt;/head&gt;
&lt;body&gt;
    &lt;h2&gt;Live Data from Python&lt;/h2&gt;
    &lt;canvas id="chart" width="800" height="350"&gt;&lt;/canvas&gt;
    &lt;div id="stats"&gt;Waiting for data...&lt;/div&gt;

    &lt;script&gt;
        const canvas = document.getElementById("chart");
        const ctx = canvas.getContext("2d");
        const statsEl = document.getElementById("stats");
        const maxPoints = 200;
        const dataPoints = [];

        function drawChart() {
            const w = canvas.width;
            const h = canvas.height;
            ctx.clearRect(0, 0, w, h);

            if (dataPoints.length &lt; 2) return;

            // Determine Y range
            const values = dataPoints.map(p =&gt; p.value);
            const minVal = Math.min(...values) - 10;
            const maxVal = Math.max(...values) + 10;
            const range = maxVal - minVal || 1;

            // Draw grid lines
            ctx.strokeStyle = "#333";
            ctx.lineWidth = 0.5;
            for (let i = 0; i &lt;= 4; i++) {
                const y = (i / 4) * h;
                ctx.beginPath();
                ctx.moveTo(0, y);
                ctx.lineTo(w, y);
                ctx.stroke();
            }

            // Draw zero line
            const zeroY = h - ((0 - minVal) / range) * h;
            ctx.strokeStyle = "#555";
            ctx.lineWidth = 1;
            ctx.setLineDash([4, 4]);
            ctx.beginPath();
            ctx.moveTo(0, zeroY);
            ctx.lineTo(w, zeroY);
            ctx.stroke();
            ctx.setLineDash([]);

            // Draw the data line
            ctx.strokeStyle = "#03dac6";
            ctx.lineWidth = 2;
            ctx.beginPath();
            for (let i = 0; i &lt; dataPoints.length; i++) {
                const x = (i / (maxPoints - 1)) * w;
                const y = h - ((dataPoints[i].value - minVal) / range) * h;
                if (i === 0) ctx.moveTo(x, y);
                else ctx.lineTo(x, y);
            }
            ctx.stroke();

            // Draw the latest point
            const lastX = ((dataPoints.length - 1) / (maxPoints - 1)) * w;
            const lastY = h - ((dataPoints[dataPoints.length - 1].value - minVal) / range) * h;
            ctx.fillStyle = "#bb86fc";
            ctx.beginPath();
            ctx.arc(lastX, lastY, 4, 0, Math.PI * 2);
            ctx.fill();
        }

        document.addEventListener("PytoniumReady", function () {
            Pytonium.registerForStateUpdates("graph", "point", function (raw) {
                const point = JSON.parse(raw);
                dataPoints.push(point);

                // Keep only the last N points
                if (dataPoints.length &gt; maxPoints) {
                    dataPoints.shift();
                }

                drawChart();

                // Update stats display
                statsEl.textContent =
                    "Points: " + dataPoints.length +
                    " | Latest: " + point.value +
                    " | Time: " + point.time;
            });
        });
    &lt;/script&gt;
&lt;/body&gt;
&lt;/html&gt;
</code></pre>

